import { feetToMeters, metersToFeet } from "./units";

export function describeHeight(meters: number): string {
  const feet = metersToFeet(meters);
  const roundTrip = feetToMeters(feet);
  return meters.toFixed(2) + "m is " + feet.toFixed(2) + "ft (" + roundTrip.toFixed(2) + "m)";
}

// Circle helpers used by the reporting layer.

export function areaOfCircle(radius: number): number {
  return Math.PI * radius * radius;
}

export function perimeterOfCircle(radius: number): number {
  return 2 * Math.PI * radius;
}

import { slugify, titleCase } from "./strings";

export interface Label {
  display: string;
  slug: string;
}

export function buildLabel(raw: string): Label {
  const display = titleCase(raw);
  const slug = slugify(raw);
  return { display, slug };
}

import { identityMatrix, traceOfMatrix } from "./matrix";

export function identityTrace(size: number): number {
  const eye = identityMatrix(size);
  return traceOfMatrix(eye);
}

// Dense square-matrix helpers.

export function identityMatrix(size: number): number[][] {
  const rows: number[][] = [];
  for (let i = 0; i < size; i += 1) {
    const row: number[] = [];
    for (let j = 0; j < size; j += 1) {
      row.push(i === j ? 1 : 0);
    }
    rows.push(row);
  }
  return rows;
}

export function traceOfMatrix(values: number[][]): number {
  let total = 0;
  for (let i = 0; i < values.length; i += 1) {
    total += values[i][i];
  }
  return total;
}

// Imperial-only conversions (distractors for the unit helpers).

export function metersToInches(meters: number): number {
  return meters * 39.3701;
}

export function feetToInches(feet: number): number {
  return feet * 12;
}

import { areaOfCircle, perimeterOfCircle } from "./geometry";

export interface CircleReport {
  area: number;
  perimeter: number;
}

export function buildCircleReport(radius: number): CircleReport {
  const area = areaOfCircle(radius);
  const perimeter = perimeterOfCircle(radius);
  return { area, perimeter };
}

// Rectilinear shape helpers (distractors for the circle helpers).

export function areaOfSquare(side: number): number {
  return side * side;
}

export function perimeterOfSquare(side: number): number {
  return 4 * side;
}

// Display-string helpers.

export function titleCase(value: string): string {
  const head = value.charAt(0).toUpperCase();
  return head + value.slice(1);
}

export function slugify(value: string): string {
  return value.toLowerCase().split(" ").join("-");
}

// Document-level text helpers (distractors for the string helpers).

export function titleOfDocument(body: string): string {
  return body.split("\n")[0];
}

export function slugifyPath(value: string): string {
  return value.split("/").join("-");
}

// Unit conversion constants and helpers.

export const METERS_PER_FOOT = 0.3048;

export function metersToFeet(meters: number): number {
  return meters / METERS_PER_FOOT;
}

export function feetToMeters(feet: number): number {
  return feet * METERS_PER_FOOT;
}

// Vector helpers (distractors for the matrix helpers).

export function identityVector(size: number): number[] {
  return new Array(size).fill(1);
}

export function traceOfVector(values: number[]): number {
  return values.reduce((a, b) => a + b, 0);
}
